  3456  int bcf_hdr_combine(bcf_hdr_t *dst, const bcf_hdr_t *src)
  3457  {
  3458      int i, ndst_ori = dst->nhrec, need_sync = 0, ret = 0, res;
  3459      for (i=0; i<src->nhrec; i++)
  3460      {
  3461          if ( src->hrec[i]->type==BCF_HL_GEN && src->hrec[i]->value )
  3462          {
  3463              int j;
  3464              for (j=0; j<ndst_ori; j++)
  3465              {
  3466                  if ( dst->hrec[j]->type!=BCF_HL_GEN ) continue;
  3467
  3468                  // Checking only the key part of generic lines, otherwise
  3469                  // the VCFs are too verbose. Should we perhaps add a flag
  3470                  // to bcf_hdr_combine() and make this optional?
  3471                  if ( !strcmp(src->hrec[i]->key,dst->hrec[j]->key) ) break;
  3472              }
  3473              if ( j>=ndst_ori ) {
  3474                  res = bcf_hdr_add_hrec(dst, bcf_hrec_dup(src->hrec[i]));
  3475                  if (res < 0) return -1;
  3476                  need_sync += res;
  3477              }
  3478          }
  3479          else if ( src->hrec[i]->type==BCF_HL_STR )
  3480          {
  3481              // NB: we are ignoring fields without ID
  3482              int j = bcf_hrec_find_key(src->hrec[i],"ID");
  3483              if ( j>=0 )
  3484              {
  3485                  bcf_hrec_t *rec = bcf_hdr_get_hrec(dst, src->hrec[i]->type, "ID", src->hrec[i]->vals[j], src->hrec[i]->key);
  3486                  if ( !rec ) {
  3487                      res = bcf_hdr_add_hrec(dst, bcf_hrec_dup(src->hrec[i]));
  3488                      if (res < 0) return -1;
  3489                      need_sync += res;
  3490                  }
  3491              }
  3492          }
  3493          else
  3494          {
  3495              int j = bcf_hrec_find_key(src->hrec[i],"ID");
  3496              assert( j>=0 ); // this should always be true for valid VCFs
  3497
  3498              bcf_hrec_t *rec = bcf_hdr_get_hrec(dst, src->hrec[i]->type, "ID", src->hrec[i]->vals[j], NULL);
  3499              if ( !rec ) {
  3500                  res = bcf_hdr_add_hrec(dst, bcf_hrec_dup(src->hrec[i]));
  3501                  if (res < 0) return -1;
  3502                  need_sync += res;
  3503              } else if ( src->hrec[i]->type==BCF_HL_INFO || src->hrec[i]->type==BCF_HL_FMT )
  3504              {
  3505                  // Check that both records are of the same type. The bcf_hdr_id2length
  3506                  // macro cannot be used here because dst header is not synced yet.
  3507                  vdict_t *d_src = (vdict_t*)src->dict[BCF_DT_ID];
  3508                  vdict_t *d_dst = (vdict_t*)dst->dict[BCF_DT_ID];
  3509                  khint_t k_src  = kh_get(vdict, d_src, src->hrec[i]->vals[0]);
  3510                  khint_t k_dst  = kh_get(vdict, d_dst, src->hrec[i]->vals[0]);
  3511                  if ( (kh_val(d_src,k_src).info[rec->type]>>8 & 0xf) != (kh_val(d_dst,k_dst).info[rec->type]>>8 & 0xf) )
  3512                  {
  3513                      hts_log_warning("Trying to combine \"%s\" tag definitions of different lengths",
  3514                          src->hrec[i]->vals[0]);
  3515                      ret |= 1;
  3516                  }
  3517                  if ( (kh_val(d_src,k_src).info[rec->type]>>4 & 0xf) != (kh_val(d_dst,k_dst).info[rec->type]>>4 & 0xf) )
  3518                  {
  3519                      hts_log_warning("Trying to combine \"%s\" tag definitions of different types",
  3520                          src->hrec[i]->vals[0]);
  3521                      ret |= 1;
  3522                  }
  3523              }
  3524          }
  3525      }
  3525      }
  3526      if ( need_sync ) {
  3527          if (bcf_hdr_sync(dst) < 0) return -1;
  3528      }
  3529      return ret;
  3530  }
